// Inserts data/fit-guides/<topicId>.md into src/content/posts/<topicId>.md,
// right after the intro paragraph, between marker comments so re-running
// replaces (never duplicates) the section. Fit guides are written by hand /
// computed deterministically — not generated by the model — so any math in
// them is verifiable.
//   node scripts/apply-fit-guides.mjs [topicId ...]
import fs from 'node:fs';
import path from 'node:path';

const GUIDES = './data/fit-guides';
const POSTS = './src/content/posts';
const START = '<!-- fit-guide:start -->';
const END = '<!-- fit-guide:end -->';

const only = process.argv.slice(2);
const ids = fs
	.readdirSync(GUIDES)
	.filter((f) => f.endsWith('.md'))
	.map((f) => f.replace(/\.md$/, ''))
	.filter((id) => !only.length || only.includes(id));

for (const id of ids) {
	const postPath = path.join(POSTS, `${id}.md`);
	if (!fs.existsSync(postPath)) {
		console.warn(`skip ${id}: no post`);
		continue;
	}
	let raw = fs.readFileSync(postPath, 'utf-8');
	const nl = raw.includes('\r\n') ? '\r\n' : '\n';
	const guide = fs.readFileSync(path.join(GUIDES, `${id}.md`), 'utf-8').trim().replace(/\r?\n/g, nl);
	const block = `${START}${nl}${guide}${nl}${END}`;

	if (raw.includes(START)) {
		raw = raw.replace(new RegExp(`${START}[\s\S]*?${END}`), () => block);
	} else {
		// Insert before the first H2 after the frontmatter (i.e. after the intro).
		const fmEnd = raw.indexOf(`${nl}---${nl}`, 3) + `${nl}---${nl}`.length;
		const h2 = raw.indexOf(`${nl}## `, fmEnd);
		if (h2 === -1) {
			console.warn(`skip ${id}: no H2 to anchor on`);
			continue;
		}
		raw = raw.slice(0, h2) + `${nl}${nl}${block}${nl}` + raw.slice(h2);
	}
	fs.writeFileSync(postPath, raw);
	console.log(`applied fit guide -> ${id}`);
}
